      "level": "understand",
      "question": "What happens if you say 'one MORE' instead of 'one less'?",
      "options": [
        "You count forwards.",
        "You count backwards.",
        "You repeat a number."
      ],
      "correct_index": 0,
      "explanation": "When you say 'one more' instead of 'one less', you are counting in the forward direction.",
      "selected_because": "the teacher warned against saying 'one more' instead of 'one less'",
      "distractor_misconceptions": {
        "1": "Confuses 'one more' with 'one less'",
        "2": "Confuses saying 'one more' with repeating a number"
      },
      "option_feedback": {
        "correct": "That's right! Saying 'one more' means you are counting up, or forwards.",
        "wrong": {
          "1": "When we count backwards, we always say 'one less'. Saying 'one more' makes us count forwards. Remember Bunty's hopscotch, going down one step at a time.",
          "2": "Repeating a number is a different mistake. Saying 'one more' instead of 'one less' makes you count forwards, not repeat a number. Remember to always take 'one less' when counting backwards."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Children flip direction mid-run and say one MORE — 5 then 6 — or repeat a number: 5, 5, 3.",
      "teaching_error": null
    }
  ]
}
